const payload = $json.body ?? $json;
const forbiddenTerms = ['patient name', 'symptom', 'diagnosis', 'treatment detail', 'insurance id', 'member id', 'appointment reason', 'clinical note', 'x-ray', 'payment card'];
const haystack = JSON.stringify(payload).toLowerCase();
const flaggedTerms = forbiddenTerms.filter((term) => haystack.includes(term));
const accepted = flaggedTerms.length === 0 && payload.phiAcknowledgement === true;
return [{ json: { accepted, leadId: accepted ? `DEMO-DENTAL-${Date.now()}` : null, flaggedTerms, message: accepted ? 'Accepted demo non-PHI dental practice audit lead.' : 'Rejected for demo review. Remove patient-specific details before submitting.', lead: accepted ? { practiceName: payload.practiceName, contactName: payload.contactName, workEmail: payload.workEmail, workPhone: payload.workPhone, website: payload.website, providerCount: payload.providerCount, monthlyPatientVolume: payload.monthlyPatientVolume, currentTools: payload.currentTools, biggestLeak: payload.biggestLeak, source: payload.source ?? 'dental-practice-audit' } : payload } }];
